export function popupCategory(title=''){if(/shadow|motion blur|colour|color|texture|canvas|object options|mesh|shape|image|svg/i.test(title))return 'artwork';if(/animation|animate|graph|keyframe|sequence|sequencer|tempo|motion|playback|loop|audio/i.test(title))return 'animation';if(/arrange|layers|group|selection/i.test(title))return 'arrange';return 'general';}
export function decoratePopup(dialog,title){if(!dialog)return;dialog.classList.add('calm-popup');dialog.dataset.popupCategory=popupCategory(title||dialog.querySelector('h2,header strong')?.textContent||dialog.getAttribute('aria-label')||'');}
export function bindPopupStyles(){document.querySelectorAll('dialog').forEach(d=>decoratePopup(d));if(typeof MutationObserver==='undefined')return ()=>{};const observer=new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes){if(node.nodeType!==1||node.namespaceURI!=='http://www.w3.org/1999/xhtml')continue;if(node.matches('dialog'))decoratePopup(node);node.querySelectorAll('dialog').forEach(d=>decoratePopup(d));}});observer.observe(document.body,{childList:true,subtree:true});return ()=>observer.disconnect();}
